const crypto = require('crypto');
const { Client } = require('pg');
const PDFDocument = require('pdfkit');

const SECRET = String($env.CHAT_JWT_SECRET || '');
const reply = (status, body) => [{ json: { _status: status, _body: body } }];
const fail = (status, code, message) => reply(status, { ok: false, error: { code, message } });
if (!SECRET || !$env.YAVIBOT_DB_PASSWORD) return fail(500, 'CONFIGURACION', 'Faltan CHAT_JWT_SECRET o YAVIBOT_DB_PASSWORD en n8n.');

function verifyChat(token) {
  if (!token) return null;
  const parts = String(token).split('.');
  if (parts.length !== 3) return null;
  const [h, p, s] = parts;
  const b64 = b => Buffer.from(b).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
  const expected = b64(crypto.createHmac('sha256', SECRET).update(h + '.' + p).digest());
  const left = Buffer.from(s);
  const right = Buffer.from(expected);
  if (left.length !== right.length || !crypto.timingSafeEqual(left, right)) return null;
  try {
    const claims = JSON.parse(Buffer.from(p.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString());
    if (claims.typ !== 'chat' || (claims.exp && claims.exp < Math.floor(Date.now() / 1000))) return null;
    return claims;
  } catch { return null; }
}

function normalizePlate(value) {
  const compact = String(value || '').trim().toUpperCase().replace(/\s+/g, '').replace(/-/g, '');
  if (!/^(?=.*[A-Z])(?=.*[0-9])[A-Z0-9]{5,8}$/.test(compact)) return null;
  return /^[A-Z]{3}[0-9]{3,4}$/.test(compact) ? compact.slice(0, 3) + '-' + compact.slice(3) : compact;
}
function vehicleLabel(type) { return type === 'MOTO' ? 'Motocicleta' : 'Automóvil'; }
function modalityLabel(modality) { return modality === 'MENSUAL' ? 'Mensual' : 'Diaria'; }
function requestCode(id) { return 'TK-' + String(id).padStart(6, '0'); }
function dateText(value) {
  if (!value) return null;
  const raw = String(value);
  const isoMatch = raw.match(/\d{4}-\d{2}-\d{2}/);
  if (isoMatch) return isoMatch[0];
  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) return null;
  const pad = number => String(number).padStart(2, '0');
  return parsed.getFullYear() + '-' + pad(parsed.getMonth() + 1) + '-' + pad(parsed.getDate());
}
function dateDisplay(value) {
  const iso = dateText(value);
  if (!iso) return '';
  const [year, month, day] = iso.split('-');
  return day + '/' + month + '/' + year;
}

async function snapshot(client, person) {
  const user = (await client.query(
    `SELECT id, estado FROM parqueadero_usuarios
      WHERE (tipo_usuario='ESTUDIANTE' AND estudiante_id=$1::bigint AND $2::varchar(20)='ESTUDIANTE')
         OR (tipo_usuario='DOCENTE' AND docente_id=$1::bigint AND $2::varchar(20)='DOCENTE')
      LIMIT 1`, [person.id, person.tipoUsuario])).rows[0];
  if (!user) return { vehicle: null, ticket: null };
  const vehicle = (await client.query(
    `SELECT id::int AS id, UPPER(placa) AS plate, tipo_vehiculo AS type FROM parqueadero_vehiculos
      WHERE parqueadero_usuario_id = $1 AND activo = true ORDER BY es_principal DESC, id DESC LIMIT 1`, [user.id])).rows[0] || null;
  const row = (await client.query(
    `SELECT pp.id::int AS request_id, pp.estado AS payment_status, pp.fecha_pago, pp.fecha_inicio, pp.fecha_fin,
            pp.motivo_rechazo, pp.monto, pm.modalidad, pv.id::int AS vehicle_id, UPPER(pv.placa) AS plate, pv.tipo_vehiculo AS vehicle_type,
            pa.id::int AS authorization_id, pa.estado AS authorization_status
       FROM parqueadero_pagos pp
       JOIN parqueadero_modalidades pm ON pm.id = pp.modalidad_id
       LEFT JOIN parqueadero_vehiculos pv ON pv.id = pp.vehiculo_id
       LEFT JOIN parqueadero_autorizaciones pa ON pa.pago_id = pp.id
      WHERE pp.parqueadero_usuario_id = $1 AND pp.origen_solicitud = 'YAVIBOT'
      ORDER BY pp.id DESC LIMIT 1`, [user.id])).rows[0];
  if (!row) return { vehicle, ticket: null };
  const state = row.authorization_id && row.payment_status === 'APROBADO' ? 'APROBADO' : row.payment_status;
  return { vehicle, ticket: {
    requestId: row.request_id, code: requestCode(row.request_id), plate: row.plate || vehicle?.plate || '',
    vehicleType: row.vehicle_type || vehicle?.type || 'AUTO', vehicleTypeLabel: vehicleLabel(row.vehicle_type || vehicle?.type),
    modality: row.modalidad || 'DIARIO', modalityLabel: modalityLabel(row.modalidad), amount: Number(row.monto || 0),
    requestedAt: row.fecha_pago, state, validFrom: dateText(row.fecha_inicio),
    validUntil: row.fecha_fin ? dateText(row.fecha_fin) + 'T23:59:00-05:00' : null,
    authorizationId: row.authorization_id || null, rejectionReason: row.motivo_rechazo || null
  } };
}

const claims = verifyChat($json.headers?.['x-chat-session'] || $json.headers?.['X-Chat-Session']);
if (!claims) return fail(401, 'NO_AUTENTICADO', 'Sesión de chat no válida o expirada.');
const body = $json.body || {};
const action = String(body.action || '').toLowerCase();
const client = new Client({
  host: $env.YAVIBOT_DB_HOST || 'postgres', port: Number($env.YAVIBOT_DB_PORT || 5432),
  user: $env.YAVIBOT_DB_USER, password: $env.YAVIBOT_DB_PASSWORD, database: $env.YAVIBOT_DB_NAME || 'yavibot'
});
await client.connect();
try {
  const person = (await client.query(
    `SELECT e.id, e.cedula, e.nombres, e.correo, 'ESTUDIANTE'::text AS "tipoUsuario"
       FROM estudiantes e WHERE e.cedula = $1
     UNION ALL
     SELECT d.id, d.cedula, d.nombre_docente AS nombres, d.correo, 'DOCENTE'::text AS "tipoUsuario"
       FROM docentes d WHERE d.cedula = $1
         AND NOT EXISTS (SELECT 1 FROM estudiantes e WHERE e.cedula = $1)
     LIMIT 1`, [claims.sub])).rows[0];
  if (!person) return fail(404, 'NO_ENCONTRADO', 'No se encontró el usuario autenticado.');
  if (action === 'estado') return reply(200, { ok: true, data: await snapshot(client, person) });

  if (action === 'solicitar') {
    const type = String(body.vehicleType || '').toUpperCase();
    const modalityCode = String(body.modality || '').toUpperCase();
    const plate = normalizePlate(body.plate);
    if (!['AUTO', 'MOTO'].includes(type)) return fail(400, 'VALIDACION', 'Selecciona un tipo de vehículo válido.');
    if (!['DIARIO', 'MENSUAL'].includes(modalityCode)) return fail(400, 'VALIDACION', 'Selecciona una modalidad valida.');
    if (!plate) return fail(400, 'VALIDACION', 'Ingresa una placa válida.');
    await client.query('BEGIN');
    try {
      let parkingUser = (await client.query(
        `SELECT id, estado FROM parqueadero_usuarios
          WHERE (tipo_usuario='ESTUDIANTE' AND estudiante_id=$1::bigint AND $2::varchar(20)='ESTUDIANTE')
             OR (tipo_usuario='DOCENTE' AND docente_id=$1::bigint AND $2::varchar(20)='DOCENTE')
          FOR UPDATE`, [person.id, person.tipoUsuario])).rows[0];
      if (!parkingUser) parkingUser = (await client.query(
        `INSERT INTO parqueadero_usuarios (tipo_usuario, estudiante_id, docente_id, estado)
         VALUES (
           $2::varchar(20),
           CASE WHEN $2::varchar(20)='ESTUDIANTE' THEN $1::bigint END,
           CASE WHEN $2::varchar(20)='DOCENTE' THEN $1::bigint END,
           'ACTIVO'
         )
         RETURNING id, estado`, [person.id, person.tipoUsuario])).rows[0];
      if (parkingUser.estado !== 'ACTIVO') { await client.query('ROLLBACK'); return fail(403, 'PARQUEADERO_INACTIVO', 'Tu acceso al servicio de parqueadero está inhabilitado.'); }
      const current = await snapshot(client, person);
      if (current.ticket?.state === 'PENDIENTE' || (current.ticket?.state === 'APROBADO' && current.ticket.authorizationId)) {
        await client.query('COMMIT'); return reply(200, { ok: true, data: current });
      }
      const conflict = (await client.query(
        'SELECT id, parqueadero_usuario_id FROM parqueadero_vehiculos WHERE upper(placa) = upper($1) FOR UPDATE', [plate])).rows[0];
      if (conflict && Number(conflict.parqueadero_usuario_id) !== Number(parkingUser.id)) {
        await client.query('ROLLBACK'); return fail(409, 'PLACA_REGISTRADA', 'La placa ingresada ya está registrada a nombre de otra persona.');
      }
      await client.query(
        'UPDATE parqueadero_vehiculos SET es_principal = false, actualizado_en = now() WHERE parqueadero_usuario_id = $1 AND activo = true AND es_principal = true',
        [parkingUser.id]);
      let vehicle;
      if (conflict) vehicle = (await client.query(
        'UPDATE parqueadero_vehiculos SET tipo_vehiculo=$2, activo=true, es_principal=true, actualizado_en=now() WHERE id=$1 RETURNING id,placa,tipo_vehiculo',
        [conflict.id, type])).rows[0];
      else vehicle = (await client.query(
        'INSERT INTO parqueadero_vehiculos (parqueadero_usuario_id,placa,tipo_vehiculo,es_principal,activo) VALUES ($1,$2,$3,true,true) RETURNING id,placa,tipo_vehiculo',
        [parkingUser.id, plate, type])).rows[0];
      const modality = (await client.query(
        `SELECT id, precio FROM parqueadero_modalidades WHERE modalidad=$1 AND tipo_vehiculo=$2 AND activo=true AND precio IS NOT NULL`, [modalityCode, type])).rows[0];
      if (!modality) { await client.query('ROLLBACK'); return fail(409, 'TARIFA_NO_CONFIGURADA', 'No existe una tarifa activa para esta modalidad y tipo de vehiculo.'); }
      const payment = (await client.query(
        `INSERT INTO parqueadero_pagos (parqueadero_usuario_id,vehiculo_id,modalidad_id,monto,metodo_pago,fecha_pago,fecha_inicio,fecha_fin,estado,origen_solicitud)
         VALUES ($1,$2,$3,$4,'EFECTIVO',now(),CURRENT_DATE,CASE WHEN $5='MENSUAL' THEN CASE WHEN EXTRACT(DAY FROM CURRENT_DATE)=1 THEN (date_trunc('month',CURRENT_DATE)+INTERVAL '1 month - 1 day')::date ELSE (CURRENT_DATE + INTERVAL '1 month')::date END ELSE CURRENT_DATE END,'PENDIENTE','YAVIBOT') RETURNING id`,
        [parkingUser.id, vehicle.id, modality.id, modality.precio, modalityCode])).rows[0];
      await client.query(
        `INSERT INTO eventos (tipo,payload,origen) VALUES ('TicketParqueaderoSolicitado',$1::jsonb,'chatbot')`,
        [JSON.stringify({ requestId: payment.id, personId: person.id, tipoUsuario: person.tipoUsuario, plate, vehicleType: type, modality: modalityCode })]);
      await client.query('COMMIT');
      return reply(201, { ok: true, data: await snapshot(client, person) });
    } catch (error) { await client.query('ROLLBACK'); throw error; }
  }

  if (action === 'descargar') {
    const requestId = Number(body.requestId);
    if (!Number.isInteger(requestId) || requestId <= 0) return fail(400, 'VALIDACION', 'El ticket solicitado no es válido.');
    const ticket = (await client.query(
      `SELECT pp.id,COALESCE(e.nombres,d.nombre_docente) AS nombres,COALESCE(e.cedula,d.cedula) AS cedula,
              UPPER(pv.placa) AS plate,pv.tipo_vehiculo,pa.id AS authorization_id,pa.fecha_inicio,pa.fecha_fin,pa.estado
       FROM parqueadero_pagos pp JOIN parqueadero_usuarios pu ON pu.id=pp.parqueadero_usuario_id
       LEFT JOIN estudiantes e ON e.id=pu.estudiante_id
       LEFT JOIN docentes d ON d.id=pu.docente_id
       JOIN parqueadero_vehiculos pv ON pv.id=pp.vehiculo_id
       JOIN parqueadero_autorizaciones pa ON pa.pago_id=pp.id
       WHERE pp.id=$1::bigint
         AND pu.tipo_usuario=$2::varchar(20)
         AND (
           (pu.estudiante_id=$3::bigint AND $2::varchar(20)='ESTUDIANTE')
           OR
           (pu.docente_id=$3::bigint AND $2::varchar(20)='DOCENTE')
         )
         AND pp.estado='APROBADO' AND pa.estado='VIGENTE'`, [requestId, person.tipoUsuario, person.id])).rows[0];
    if (!ticket) return fail(404, 'TICKET_NO_DISPONIBLE', 'El ticket todavía no está aprobado o ya no se encuentra vigente.');
    const pdf = await new Promise((resolve, reject) => {
      const doc = new PDFDocument({ size:'A4', margin:54 }); const chunks=[];
      doc.on('data', c => chunks.push(c)); doc.on('end', () => resolve(Buffer.concat(chunks))); doc.on('error', reject);
      doc.rect(42,42,511,310).lineWidth(2).stroke('#12325b');
      doc.fillColor('#12325b').fontSize(22).text('TICKET DE PARQUEADERO',{align:'center'});
      doc.moveDown(.4).fillColor('#e56b1f').fontSize(16).text(requestCode(ticket.id),{align:'center'});
      doc.moveDown(1.5).fillColor('#1d2735').fontSize(12).text('Titular: '+ticket.nombres).text('Cédula: '+ticket.cedula)
        .text('Placa: '+ticket.plate).text('Tipo: '+vehicleLabel(ticket.tipo_vehiculo))
        .text('Vigencia: '+dateDisplay(ticket.fecha_inicio)+' – '+dateDisplay(ticket.fecha_fin)+' · 23:59');
      doc.moveDown(1.2).fillColor('#16834a').fontSize(15).text('APROBADO',{align:'center'});
      doc.moveDown(1.5).fillColor('#59677a').fontSize(9).text('Instituto Superior Tecnológico Yavirac · Documento generado por YaviBot',{align:'center'});
      doc.end();
    });
    return reply(200, { ok:true, data:{ filename:'ticket-parqueadero-'+requestCode(ticket.id)+'.pdf', contentBase64:pdf.toString('base64') } });
  }
  return fail(400, 'ACCION_INVALIDA', 'La acción solicitada no es válida.');
} catch (error) {
  console.log('YaviBot Parking:', { message: error.message, code: error.code, detail: error.detail, constraint: error.constraint, stack: error.stack });
  return fail(500, 'ERROR_INTERNO', 'No fue posible procesar la solicitud de parqueadero.');
} finally { await client.end(); }
